/**
 * Idempotent production-safe glacier seed.
 *
 * Run from inside the API container:
 *   npx ts-node scripts/seed-glaciers.ts
 *
 * Notes:
 * - PostgreSQL UUIDs are generated by the database; seed-data IDs are not used.
 * - Records are matched by RGI ID when available, otherwise by name.
 * - Existing records are updated instead of duplicated.
 * - district_id is resolved by district name only where the district assignment
 *   is explicitly known from the existing CryoHealth seed. Other records remain NULL.
 * - This is curated named-glacier seed data, not a complete RGI polygon inventory.
 */
